  // tails[i] will store the smallest tail of all increasing subsequences of length i+1
  const tails = [];

  for (let x of tab) {
    let left = 0;
    let right = tails.length;

    // Binary search to find the insertion point for x
    while (left < right) {
      let mid = Math.floor((left + right) / 2);
      if (tails[mid] < x) {
        left = mid + 1;
      } else {
        right = mid;
      }
