  if (a.length > b.length) return medianeDeuxTries(b, a);

  const x = a.length;
  const y = b.length;
  let low = 0;
  let high = x;
  const halfLen = Math.floor((x + y + 1) / 2);

  while (low <= high) {
    const i = Math.floor((low + high) / 2);
    const j = halfLen - i;

    if (i < x && b[j - 1] > a[i]) {
      low = i + 1;
    } else if (i > 0 && a[i - 1] > b[j]) {
      high = i - 1;
    } else {
      // Partition is correct
      const maxLeft = Math.max(
        i === 0 ? -Infinity : a[i - 1],
        j === 0 ? -Infinity : b[j - 1]
      );

      if ((x + y) % 2 !== 0) {
        return maxLeft;
      } else {
        const minRight = Math.min(
          i === x ? Infinity : a[i],
          j === y ? Infinity : b[j]
        );
        return (maxLeft + minRight) / 2;
      }
    }
  }
}
